pub fn parent(&self) -> Option<&Path> {
    if self.is_absolute() && self.as_u8_slice().len() == 1 {
        None
    } else {
        let mut components = self.components().collect::<Vec<_>>();
        components.pop(); // Remove the last component
        if components.is_empty() {
            Some(Path::new("/")) // Return root if no components left
        } else {
            Some(Path::new(components.join("/").as_str()))
        }
    }
}
